/** ReceivedMessage is a decoded incoming message, typed by its name. */
export type ReceivedMessage =
  | { name: typeof MessageOutgoingMessage; payload: OutgoingMessagePayload };

const receivedMessages: readonly RtCandidate[] = [
  {
    name: MessageOutgoingMessage,
    matchers: [
      { pointer: "/type", value: "message" },
    ],
    fallback: false,
    check: (payload: unknown): void => {
      validateOutgoingMessagePayload(payload, MessageOutgoingMessage);
    },
  },
];

/**
 * decodeReceivedMessage works out which incoming message data is and checks
 * it. It throws UnknownMessageError when nothing matches and
 * AmbiguousMessageError when several messages match.
 */
export function decodeReceivedMessage(data: string): ReceivedMessage {
  const [name, payload] = rtDecodeMessage(data, receivedMessages);

  return { name, payload } as ReceivedMessage;
}

/** Handler receives incoming messages. Implement only the methods you need. */
export interface Handler {
  /**
   * A message was sent to a channel.
   * Payload: OutgoingMessagePayload.
   */
  handleOutgoingMessage?(payload: OutgoingMessagePayload): void | Promise<void>;
  /**
   * handleUnknownMessage gets every message that matched nothing, with the
   * reason. Without it, Client.receive throws the error.
   */
  handleUnknownMessage?(
    data: string,
    error: UnknownMessageError | AmbiguousMessageError,
  ): void | Promise<void>;
}

/** dispatch passes message to the handler method for its name. */
export async function dispatch(
  handler: Handler,
  message: ReceivedMessage,
): Promise<void> {
  switch (message.name) {
    case MessageOutgoingMessage:
      await handler.handleOutgoingMessage?.(message.payload);

      return;
  }
}

/** Transport carries text frames. A browser WebSocket fits it as it is. */
export interface Transport {
  send(data: string): void | Promise<void>;
  close(): void;
}

